(function () {
  // ── shared helpers (SVG, tweening) ─────────────────────────────────────────
  var NS = "http://www.w3.org/2000/svg";
  var svg = document.getElementById("scene");
  var labelEl = document.getElementById("step-label");
  var captionEl = document.getElementById("caption");

  function el(name, attrs, parent) {
    var node = document.createElementNS(NS, name);
    for (var key in attrs) node.setAttribute(key, attrs[key]);
    if (parent) parent.appendChild(node);
    return node;
  }
  function txt(parent, x, y, cls, str, anchor) {
    var t = el("text", { x: x, y: y, class: cls }, parent);
    if (anchor) t.setAttribute("text-anchor", anchor);
    t.textContent = str;
    return t;
  }
  function show(node, on) {
    node.setAttribute("opacity", on ? "1" : "0");
  }
  function place(node, x, y) {
    node.style.transform = "translate(" + x + "px," + y + "px)";
  }
  function setLine(node, x1, y1, x2, y2) {
    node.setAttribute("x1", x1);
    node.setAttribute("y1", y1);
    node.setAttribute("x2", x2);
    node.setAttribute("y2", y2);
  }
  function lerp(a, b, e) {
    return a + (b - a) * e;
  }
  function round1(v) {
    return (Math.round(v * 10) / 10).toFixed(1);
  }

  // Eased animation. fn(e) is called with e from 0 to 1. Without
  // requestAnimationFrame (or with ms = 0) it jumps straight to fn(1).
  var animTokens = {};
  function anim(key, ms, fn) {
    var token = (animTokens[key] || 0) + 1;
    animTokens[key] = token;
    if (typeof requestAnimationFrame !== "function" || ms <= 0) {
      fn(1);
      return;
    }
    var start = null;
    function frame(now) {
      if (animTokens[key] !== token) return;
      if (start === null) start = now;
      var p = Math.min(1, (now - start) / ms);
      var e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
      fn(e);
      if (p < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  // Arrowheads, one marker per colour.
  var COLORS = { g: "#1DB584", y: "#E2B44A", p: "#F472B6", b: "#38BDF8", w: "#c9dccf", r: "#F87171" };
  var defs = el("defs", {}, svg);
  Object.keys(COLORS).forEach(function (k) {
    var m = el("marker", { id: "ah-" + k, viewBox: "0 0 10 10", refX: 9, refY: 5, markerUnits: "userSpaceOnUse", markerWidth: 13, markerHeight: 13, orient: "auto" }, defs);
    el("path", { d: "M0 0 L10 5 L0 10 Z", fill: COLORS[k] }, m);
  });
  function arrow(parent, colorKey, width) {
    return el("line", { x1: 0, y1: 0, x2: 0, y2: 0, stroke: COLORS[colorKey], "stroke-width": width || 3, "marker-end": "url(#ah-" + colorKey + ")", "stroke-linecap": "round" }, parent);
  }
  function polygon(parent, cls) {
    return el("polygon", { points: "", class: cls }, parent);
  }
  function setPoly(node, pts) {
    node.setAttribute("points", pts.map(function (p) { return p[0].toFixed(1) + "," + p[1].toFixed(1); }).join(" "));
  }
  function lerpPts(a, b, e) {
    return a.map(function (p, i) { return [lerp(p[0], b[i][0], e), lerp(p[1], b[i][1], e)]; });
  }
  // Maps maths coordinates (x right, y up) to screen pixels.
  function makePlane(cx, cy, s) {
    return {
      x: function (v) { return cx + s * v; },
      y: function (v) { return cy - s * v; },
      pt: function (p) { return [cx + s * p[0], cy - s * p[1]]; },
      s: s, cx: cx, cy: cy
    };
  }
  function axes(parent, plane, xr, yr) {
    el("line", { x1: plane.x(-xr), y1: plane.y(0), x2: plane.x(xr), y2: plane.y(0), class: "axis" }, parent);
    el("line", { x1: plane.x(0), y1: plane.y(-yr), x2: plane.x(0), y2: plane.y(yr), class: "axis" }, parent);
  }

  // ── Module 3 helpers: graphs, curves, contour plane ───────────────────────
  // makeGraph maps maths values to pixels with separate x and y scales.
  function makeGraph(ox, oy, sx, sy) {
    return {
      ox: ox, oy: oy, sx: sx, sy: sy,
      x: function (v) { return ox + sx * v; },
      y: function (v) { return oy - sy * v; }
    };
  }
  function curveD(g, f, a, b, n) {
    var d = "";
    for (var i = 0; i <= n; i++) {
      var v = a + ((b - a) * i) / n;
      d += (i ? " L " : "M ") + g.x(v).toFixed(1) + " " + g.y(f(v)).toFixed(1);
    }
    return d;
  }
  function setD(node, d) {
    node.setAttribute("d", d);
  }
  function fmt(v, n) {
    return (Math.round(v * 100000) / 100000).toFixed(n === undefined ? 1 : n);
  }
  function drawAxes(parent, g, xmax, ymax, xticks, yticks) {
    el("line", { x1: g.x(0), y1: g.y(0), x2: g.x(xmax), y2: g.y(0), class: "axis" }, parent);
    el("line", { x1: g.x(0), y1: g.y(0), x2: g.x(0), y2: g.y(ymax), class: "axis" }, parent);
    (xticks || []).forEach(function (t) { txt(parent, g.x(t), g.y(0) + 15, "tick", String(t), "middle"); });
    (yticks || []).forEach(function (t) { txt(parent, g.x(0) - 7, g.y(t) + 4, "tick", String(t), "end"); });
  }
  function card(parent, x, y, w, h, cls) {
    return el("rect", { x: x, y: y, width: w, height: h, rx: 10, class: cls || "fillG" }, parent);
  }
  function ring(parent, cx, cy, rx, ry, cls) {
    return el("ellipse", { cx: cx, cy: cy, rx: rx, ry: ry, fill: "none", class: cls || "contour" }, parent);
  }
  function clipTo(id, x, y, w, h) {
    var c = el("clipPath", { id: id }, defs);
    el("rect", { x: x, y: y, width: w, height: h }, c);
  }

  // ── Module 4 helpers: seeded randomness, small shapes ─────────────────────
  function mulberry(seed) {
    var a = seed;
    return function () {
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  function gaussSource(rand) {
    return function () {
      var u = 1 - rand(), v = rand();
      return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
    };
  }
  function box(parent, x, y, w, h, fill, stroke, r) {
    return el("rect", { x: x, y: y, width: w, height: h, rx: r === undefined ? 6 : r, fill: fill, stroke: stroke || "none", "stroke-width": 2 }, parent);
  }
  function setBox(node, x, y, w, h) {
    node.setAttribute("x", x); node.setAttribute("y", y); node.setAttribute("width", Math.max(0, w)); node.setAttribute("height", Math.max(0, h));
  }
  function vis(list, on) {
    list.forEach(function (n) { show(n, on); });
  }

  var EXPLAIN = {"experiment":{"h":"WHAT YOU ARE LOOKING AT","t":"We toss a **fair coin twice**. Before the tosses, the result is uncertain. We will turn the result into a **number we can compute with**."},"outcomes":{"h":"THE FOUR OUTCOMES","t":"The possible outcomes are **HH, HT, TH and TT**, each with probability **1/4**. These are descriptions, not numbers: we cannot average them or put them in a formula."},"define-variable":{"h":"DEFINE A RANDOM VARIABLE","t":"Choose a rule: **X = the number of heads**. A random variable is exactly this: **a rule that gives a number to every outcome**. The rule is fixed; only which outcome occurs is random."},"map-outcomes":{"h":"MAP EACH OUTCOME TO A NUMBER","t":"Apply the rule: **HH has 2 heads, HT has 1, TH has 1, TT has 0**. Two different outcomes (HT and TH) can map to the same value."},"possible-values":{"h":"THE POSSIBLE VALUES","t":"X can take the values **0, 1 or 2**. These numbers, not the coin pictures, are what a formula can work with."},"probabilities":{"h":"PROBABILITIES OF THE VALUES","t":"Add up the outcomes that map to each value: **P(X = 0) = 1/4**, **P(X = 1) = 1/4 + 1/4 = 1/2**, **P(X = 2) = 1/4**. Values with their probabilities are the **distribution of X**."},"ml-connection":{"h":"TAKEAWAY","t":"**Features, labels and noise are random variables**: rules from “what happened” to a number. Once they are numbers we can talk about averages, spread and relationships."}};
  // ── scene ──
  var steps = [
    { id: "experiment", label: "A random experiment", caption: "Toss a fair coin twice. Before the tosses, the result is uncertain. We will turn the result into a number we can compute with." },
    { id: "outcomes", label: "The four outcomes", caption: "The possible outcomes are HH, HT, TH and TT, each with probability 1/4. These are descriptions, not numbers: we cannot average them or put them in a formula." },
    { id: "define-variable", label: "Define a random variable", caption: "Choose a rule: X = the number of heads. A random variable is exactly this, a rule that gives a number to every outcome. The rule is fixed; only which outcome occurs is random." },
    { id: "map-outcomes", label: "Map each outcome to a number", caption: "Apply the rule: HH has 2 heads, HT has 1, TH has 1, TT has 0. Two different outcomes (HT and TH) can map to the same value." },
    { id: "possible-values", label: "The possible values", caption: "X can take the values 0, 1 or 2. These numbers, not the coin pictures, are what a formula can work with." },
    { id: "probabilities", label: "Probabilities of the values", caption: "Add up the outcomes that map to each value: P(X = 0) = 1/4, P(X = 1) = 1/4 + 1/4 = 1/2, P(X = 2) = 1/4. Values with their probabilities are the distribution of X." },
    { id: "ml-connection", label: "Random variables in ML", caption: "Features, labels and noise are random variables: a rule from 'what happened' to a number. Once they are numbers we can talk about averages, spread and relationships." }
  ];

  var OUT = ["HH", "HT", "TH", "TT"];
  var VAL = [2, 1, 1, 0];
  var oy = function (i) { return 86 + i * 62; };
  var vy = function (v) { return 254 - v * 84; };
  var VX = 480;

  var coins = el("g", {}, svg);
  [250, 390].forEach(function (cx, i) {
    el("circle", { cx: cx, cy: 160, r: 52, fill: "rgba(226,180,74,0.2)", stroke: "#e2b44a", "stroke-width": 3 }, coins);
    txt(coins, cx, 172, "big", "?", "middle").setAttribute("font-size", "34");
    txt(coins, cx, 244, "note", "toss " + (i + 1), "middle");
  });
  txt(coins, 320, 70, "lbl", "two tosses of a fair coin", "middle");

  var cardsG = el("g", {}, svg);
  var cards = [];
  OUT.forEach(function (name, i) {
    var g = el("g", {}, cardsG);
    box(g, 40, oy(i) - 24, 130, 48, "rgba(226,180,74,0.16)", "#e2b44a", 10);
    txt(g, 105, oy(i) + 7, "big", name.split("").join(" "), "middle").setAttribute("font-size", "20");
    cards.push(g);
  });
  txt(cardsG, 105, 44, "lbl", "outcomes", "middle");

  var rule = el("g", {}, svg);
  box(rule, 215, 26, 210, 40, "rgba(29,181,132,0.2)", "#1db584", 10);
  txt(rule, 320, 51, "lbl lbl-g", "X = number of heads", "middle");

  var arrows = [];
  var mapG = el("g", {}, svg);
  OUT.forEach(function (name, i) {
    var a = arrow(mapG, "g", 3);
    setLine(a, 176, oy(i), VX - 34, vy(VAL[i]));
    arrows.push(a);
  });

  var valsG = el("g", {}, svg);
  txt(valsG, VX, 44, "lbl", "values of X", "middle");
  [0, 1, 2].forEach(function (v) {
    el("circle", { cx: VX, cy: vy(v), r: 26, fill: "rgba(56,189,248,0.2)", stroke: "#38bdf8", "stroke-width": 3 }, valsG);
