  });
  var sumNote = txt(probG, 570, vy(1) + 34, "note", "HT + TH: 1/4 + 1/4", "middle");

  var mlG = el("g", {}, svg);
  [["label y", "spam = 1, not spam = 0", "fillB"], ["feature x", "a house's size", "fillA"], ["noise", "measurement error", "fillG"]].forEach(function (r, i) {
    var y = 84 + i * 76;
